#!/usr/bin/env node
// Removes the flat chroma-key green background from a creature cutout
// (generated by generate-species-art-layered.mjs) and composites it onto a
// habitat background, producing a single preview PNG. This is a QA/preview
// tool — the actual app renders cutout + background as separate layers at
// runtime (see docs/lore_world_bible_ecorex_v4.md §15.4.3), it does not ship
// pre-composited flat images.
//
// Usage:
//   node scripts/composite-species-art.mjs <cutout.png> <background.png> <out.png> [--scale 0.62] [--x 0.06] [--y-margin 0.03]

import sharp from 'sharp';
import { writeFile } from 'node:fs/promises';

function parseArgs(argv) {
  const args = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--scale') args.scale = parseFloat(argv[++i]);
    else if (a === '--x') args.x = parseFloat(argv[++i]);
    else if (a === '--y-margin') args.yMargin = parseFloat(argv[++i]);
    else args._.push(a);
  }
  return args;
}

// Chroma-key removal: treat pixels where green clearly dominates red and
// blue as background, make them transparent, and desaturate residual green
// spill on the edges of the remaining (opaque) pixels.
async function removeChromaKey(inputPath) {
  const image = sharp(inputPath).ensureAlpha();
  const { data, info } = await image.raw().toBuffer({ resolveWithObject: true });
  const { width, height, channels } = info;

  for (let i = 0; i < data.length; i += channels) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];

    const isGreenBackground = g > 100 && g > r + 40 && g > b + 40;
    if (isGreenBackground) {
      data[i + 3] = 0; // fully transparent
    } else if (g > r && g > b) {
      // Despill: pull green channel down toward the average of red/blue on
      // pixels that are still part of the creature but have green fringing.
      data[i + 1] = Math.min(g, Math.round((r + b) / 2));
    }
  }

  return sharp(data, { raw: { width, height, channels } }).png();
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const [cutoutPath, backgroundPath, outPath] = args._;
  if (!cutoutPath || !backgroundPath || !outPath) {
    console.error('Uso: node scripts/composite-species-art.mjs <cutout.png> <background.png> <out.png> [--scale 0.62] [--x 0.06] [--y-margin 0.03]');
    process.exit(1);
  }

  const scale = args.scale ?? 0.62;
  const xFrac = args.x ?? 0.06;
  const yMarginFrac = args.yMargin ?? 0.03;

  const cutoutTransparent = await removeChromaKey(cutoutPath);
  const cutoutBuffer = await cutoutTransparent.toBuffer();
  const cutoutMeta = await sharp(cutoutBuffer).metadata();

  const background = sharp(backgroundPath);
  const bgMeta = await background.metadata();

  const targetWidth = Math.round(bgMeta.width * scale);
  const resizedCutout = await sharp(cutoutBuffer)
    .resize({ width: targetWidth })
    .toBuffer();
  const resizedMeta = await sharp(resizedCutout).metadata();

  const left = Math.round(bgMeta.width * xFrac);
  const top = bgMeta.height - resizedMeta.height - Math.round(bgMeta.height * yMarginFrac);

  await background
    .composite([{ input: resizedCutout, left, top }])
    .png()
    .toFile(outPath);

  console.log(`Compuesto guardado en ${outPath} (criatura ${resizedMeta.width}x${resizedMeta.height} en (${left},${top}) sobre fondo ${bgMeta.width}x${bgMeta.height}).`);
  console.log(`Ficha original de criatura: ${cutoutMeta.width}x${cutoutMeta.height}.`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
